import { arraySlot } from './client.js';
import { walletIdOf_g3120 } from './wallets.js';
import { eventFacts } from './facts.js';
import { compareLogs } from './client.js';

export async function retainedTicketLevels(s) {
  const packed = BigInt(await s.field('GAME', 'ticketBufferLevels'));
  return [Number(packed & 0xffffffn), Number((packed >> 24n) & 0xffffffn)];
}

// A physical tag is reused. Bind a commitment to the FIRST publication after
// that commitment's log, rather than treating a tag as a historical primary key.
export async function lootboxSession(s, index, { fromBlock, afterLogIndex, signal } = {}) {
  const rows = await eventFacts(s, ['LootboxRngApplied'], {
    contract: 'GAME', filters: { index }, fromBlock, signal,
  });
  const anchor = { blockNumber: fromBlock ?? 0, logIndex: afterLogIndex ?? -1 };
  const publications = rows.filter(row => compareLogs(row, anchor) > 0).sort(compareLogs);
  const applied = publications[0] ?? null;
  return { word: applied ? BigInt(applied.args.word) : 0n, applied, next: publications[1] ?? null };
}

export async function lootboxWord(s, index, options = {}) {
  return (await lootboxSession(s, index, options)).word;
}

export function inLootboxSession(row, session, commitment) {
  if (compareLogs(row, commitment) <= 0) return false;
  if (!session.applied) return false;
  return compareLogs(row, session.applied) > 0 && (!session.next || compareLogs(row, session.next) < 0);
}

export const BOX_QUEUE_LANES = 3n;
export const BOX_QUEUE_ENTRY_BITS = 85n;
export const BOX_QUEUE_ENTRY_MASK = (1n << BOX_QUEUE_ENTRY_BITS) - 1n;

/**
 * Raw queued entry at logical (buffer, position); callers bound p by the count. An 85-bit entry
 * sits at word p / 3, lane p % 3.
 */
export async function boxQueueEntry(s, buffer, position) {
  const p = BigInt(position);
  const { slot } = await s.location('GAME', 'boxQueue', [BigInt(buffer)]);
  const word = BigInt(await s.word('GAME', arraySlot(slot) + p / BOX_QUEUE_LANES));
  return (word >> ((p % BOX_QUEUE_LANES) * BOX_QUEUE_ENTRY_BITS)) & BOX_QUEUE_ENTRY_MASK;
}

/** The player's queued 85-bit box entry at (buffer, position), or 0n once settled / not theirs. */
export async function pendingBoxWord(s, _label, index, player, position = null) {
  const buffer = BigInt(index);
  if (buffer < 0n || buffer > 1n || position == null) return 0n;
  const p = BigInt(position);
  if (p < 0n) return 0n;
  const flags = BigInt(await s.field('GAME', 'rngFlagsAndNudges'));
  if (flags & (1n << 13n)) return 0n;
  const read = ((flags >> 12n) & 1n) ^ 1n;
  if (buffer === read) {
    const [cursor, count] = await Promise.all([s.field('GAME', 'boxCursor'), s.field('GAME', 'boxReadCount')]);
    if (p < BigInt(cursor) || p >= BigInt(count)) return 0n;
  } else {
    const packed = BigInt(await s.field('GAME', 'lootboxRngPacked'));
    if (p >= ((packed >> 120n) & 0xffffffffn)) return 0n;
  }
  // Three 85-bit orders per word; logical position p is word p / 3, lane p % 3
  // (LOOTBOX-COMPACT-ORDER-CLIENT-HANDOFF §3). The count bounds above keep stale lanes out.
  const entry = await boxQueueEntry(s, buffer, p);
  const id = await walletIdOf_g3120(s, player);
  return id && (entry & 0xffffffffn) === BigInt(id) ? entry : 0n;
}

// Full slot0 session state and slot3 payload. Unfinished lootbox consumers die at terminal.
export function liveLootboxWord(state, buffer, currentWord) {
  state = BigInt(state); buffer = BigInt(buffer); currentWord = BigInt(currentWord);
  if (state & (1n << 253n) || !(state & (1n << 255n)) || currentWord <= 1n) return 0n;
  return buffer === (((state >> 252n) & 1n) ^ 1n) ? currentWord : 0n;
}
